import ast
import contextlib
import io
import json
import pathlib
import re
import subprocess
import unittest
import sys
import types

COMMIT = 'eff2625e381a1ca798365c6d6ed088482d3dcf05'
REPO = pathlib.Path('/workspace/scratch/28ff48ed8b8b/LINUX-LOGIC-PRO')
source = subprocess.check_output(['git', 'show', COMMIT + ':tools/compat/logic-pro/run_baseline.py'], cwd=REPO, text=True)
node = next(n for n in ast.parse(source).body if isinstance(n, ast.FunctionDef) and n.name == 'verify_fixture_transcript')
ns = {'re': re}
exec(compile(ast.Module(body=[node], type_ignores=[]), 'verify_fixture_transcript@' + COMMIT, 'exec'), ns)
verify = ns['verify_fixture_transcript']

class Passing(unittest.TestCase):
    def test_ok(self):
        pass

class Failure(unittest.TestCase):
    def test_failure(self):
        self.fail('real assertion failure')

class SubtestFailure(unittest.TestCase):
    def test_subtest(self):
        with self.subTest(value='case'):
            self.fail('subtest failure')

class Skip(unittest.TestCase):
    @unittest.skip('deliberate skip')
    def test_skip(self):
        pass

class ExpectedFailure(unittest.TestCase):
    @unittest.expectedFailure
    def test_expected(self):
        self.fail('expected failure')

class UnexpectedSuccess(unittest.TestCase):
    @unittest.expectedFailure
    def test_unexpected(self):
        pass

class TeardownError(unittest.TestCase):
    def test_ok(self):
        pass
    @classmethod
    def tearDownClass(cls):
        raise RuntimeError('class teardown failed')

class SetupError(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        raise RuntimeError('class setup failed')
    def test_ok(self):
        pass

class SetupSkip(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        raise unittest.SkipTest('class setup skipped')
    def test_ok(self):
        pass

class TeardownSkip(unittest.TestCase):
    def test_ok(self):
        pass
    @classmethod
    def tearDownClass(cls):
        raise unittest.SkipTest('class teardown skipped')

class DocstringOutput(unittest.TestCase):
    def test_doc(self):
        """A descriptive test docstring."""
        print('diagnostic text')

class SplitOutput(unittest.TestCase):
    def test_split(self):
        print('first diagnostic')
        print('second diagnostic')

results = []
for cls in [Failure, SubtestFailure, Skip, ExpectedFailure, UnexpectedSuccess, TeardownError, SetupError, SetupSkip, TeardownSkip, DocstringOutput, SplitOutput]:
    out = io.StringIO()
    suite = unittest.TestSuite([unittest.defaultTestLoader.loadTestsFromTestCase(cls), unittest.defaultTestLoader.loadTestsFromTestCase(Passing)])
    with contextlib.redirect_stdout(out):
        result = unittest.TextTestRunner(stream=out, verbosity=2).run(suite)
    original = out.getvalue()
    transcript = re.sub(r'(?m)^(?:FAILED[^\n]*|OK \([^\n]*\))$', 'OK', original)
    expected_accept = cls in [DocstringOutput, SplitOutput]
    try:
        count = verify(transcript)
        accepted, rejection = True, None
    except ValueError as exc:
        accepted, count, rejection = False, None, str(exc)
    item = {'case': cls.__name__, 'real_success': result.wasSuccessful(), 'errors': len(result.errors), 'failures': len(result.failures), 'skips': len(result.skipped), 'expected_accept': expected_accept, 'accepted': accepted, 'count': count, 'rejection': rejection}
    if accepted != expected_accept:
        item['transcript'] = transcript
    results.append(item)
    print(json.dumps({k: v for k, v in item.items() if k != 'transcript'}))


def record_extra(name, suite, expect_accept):
    out = io.StringIO()
    with contextlib.redirect_stdout(out):
        result = unittest.TextTestRunner(stream=out, verbosity=2).run(suite)
    original = out.getvalue()
    transcript = re.sub(r'(?m)^(?:FAILED[^\n]*|OK \([^\n]*\))$', 'OK', original)
    try:
        count = verify(transcript)
        accepted, rejection = True, None
    except ValueError as exc:
        accepted, count, rejection = False, None, str(exc)
    item = {'case': name, 'real_success': result.wasSuccessful(), 'errors': len(result.errors), 'failures': len(result.failures), 'skips': len(result.skipped), 'expected_accept': expect_accept, 'accepted': accepted, 'count': count, 'rejection': rejection}
    if accepted != expect_accept:
        item['transcript'] = transcript
    results.append(item)
    print(json.dumps({k: v for k, v in item.items() if k != 'transcript'}))

for level in ['class', 'module']:
    for stage in ['setup', 'teardown', 'cleanup']:
        for behavior in ['error', 'skip', 'success']:
            for diagnostic in ['', 'lifecycle diagnostic without newline']:
                name = '_'.join([level, stage, behavior, 'no_newline' if diagnostic else 'quiet'])
                module_name = 'independent_probe_' + name
                module = types.ModuleType(module_name)
                sys.modules[module_name] = module
                case = type('IndependentLifecycleFixture', (unittest.TestCase,), {'__module__': module_name, 'test_ok': lambda self: None})
                def lifecycle(behavior=behavior, diagnostic=diagnostic):
                    if diagnostic:
                        print(diagnostic, end='')
                    if behavior == 'error':
                        raise RuntimeError('independent lifecycle error')
                    if behavior == 'skip':
                        raise unittest.SkipTest('independent lifecycle skip')
                if level == 'class':
                    if stage == 'cleanup':
                        case.setUpClass = classmethod(lambda cls, action=lifecycle: cls.addClassCleanup(action))
                    else:
                        setattr(case, 'setUpClass' if stage == 'setup' else 'tearDownClass', classmethod(lambda cls, action=lifecycle: action()))
                else:
                    if stage == 'cleanup':
                        module.setUpModule = lambda action=lifecycle: unittest.addModuleCleanup(action)
                    else:
                        setattr(module, 'setUpModule' if stage == 'setup' else 'tearDownModule', lifecycle)
                try:
                    record_extra(name, unittest.TestSuite([case('test_ok'), Passing('test_ok')]), behavior == 'success')
                finally:
                    sys.modules.pop(module_name)

loader = unittest.TestLoader()
loader_suite = loader.loadTestsFromName('independent_probe_missing_fixture_module')
record_extra('loader_import_error', unittest.TestSuite([loader_suite, Passing('test_ok')]), False)

artifacts = pathlib.Path('/workspace/scratch/28ff48ed8b8b/p004-artifacts/p004-source-00b172d8b1363c2f21deb3cbd0fb29a908ea86fc')
logs = []
for log in sorted(artifacts.glob('*.log')):
    count = verify(log.read_text())
    logs.append({'name': log.name, 'count': count})
    print('ARTIFACT', log.name, count)
print('ARTIFACT TOTAL', sum(item['count'] for item in logs))
pathlib.Path('/workspace/scratch/28ff48ed8b8b/w3_transcript_final_probe.json').write_text(json.dumps({'commit': COMMIT, 'cases': results, 'logs': logs}, indent=2) + '\n')
